/* ==========================================================================
   BUNGA KANGEN - INTERACTIVE JAVASCRIPT LOGIC
   ========================================================================== */

document.addEventListener('DOMContentLoaded', () => {

  // ==========================================
  // 1. CANVAS PARTICLE & FALLING FLOWERS ENGINE
  // ==========================================
  const canvas = document.getElementById('bgCanvas');
  const ctx = canvas.getContext('2d');

  let width = canvas.width = window.innerWidth;
  let height = canvas.height = window.innerHeight;

  window.addEventListener('resize', () => {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
  });

  // Load Custom User Flowers for Background Falling Animation
  const redRoseImg = new Image();
  redRoseImg.src = 'data:image/png;base64,';

  const rawGerberaImg = new Image();
  rawGerberaImg.src = 'data:image/jpeg;base64,';
  let redGerberaImg = rawGerberaImg;

  // Key out black background of Gerbera image to transparent canvas
  rawGerberaImg.onload = () => {
    const offscreen = document.createElement('canvas');
    offscreen.width = rawGerberaImg.width;
    offscreen.height = rawGerberaImg.height;
    const octx = offscreen.getContext('2d');
    octx.drawImage(rawGerberaImg, 0, 0);
    const imgData = octx.getImageData(0, 0, offscreen.width, offscreen.height);
    const d = imgData.data;
    for (let i = 0; i < d.length; i += 4) {
      if (d[i] < 40 && d[i+1] < 40 && d[i+2] < 40) {
        d[i+3] = 0; // Transparent
      }
    }
    octx.putImageData(imgData, 0, 0);
    redGerberaImg = offscreen;
  };

  const particles = [];
  const fallingFlowers = [];
  const clickBursts = [];

  class Particle {
    constructor() {
      this.reset();
    }
    reset() {
      this.x = Math.random() * width;
      this.y = Math.random() * height;
      this.size = Math.random() * 2.5 + 0.5;
      this.alpha = Math.random() * 0.8 + 0.2;
      this.speed = Math.random() * 0.5 + 0.2;
      this.twinkleSpeed = Math.random() * 0.03 + 0.01;
    }
    update() {
      this.alpha += Math.sin(Date.now() * this.twinkleSpeed) * 0.01;
      this.y -= this.speed;
      if (this.y < -10) this.y = height + 10;
    }
    draw() {
      ctx.save();
      ctx.globalAlpha = Math.max(0.1, Math.min(1, this.alpha));
      ctx.fillStyle = '#FFD54F';
      ctx.shadowBlur = 8;
      ctx.shadowColor = '#FFE082';
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
  }

  class FallingFlower {
    constructor() {
      this.reset();
    }
    reset() {
      this.x = Math.random() * width;
      this.y = -40 - Math.random() * 120;
      this.size = Math.random() * 18 + 34; // 34px - 52px
      this.speedY = Math.random() * 1.2 + 0.7;
      this.speedX = Math.random() * 1.2 - 0.6;
      this.rotation = Math.random() * Math.PI * 2;
      this.rotSpeed = (Math.random() - 0.5) * 0.025;
      this.oscillationSpeed = Math.random() * 0.02 + 0.01;
      this.type = Math.random() > 0.5 ? 'rose' : 'gerbera';
      this.alpha = Math.random() * 0.35 + 0.65;
    }
    update() {
      this.y += this.speedY;
      this.x += Math.sin(this.y * this.oscillationSpeed) * 1.2 + this.speedX;
      this.rotation += this.rotSpeed;

      if (this.y > height + 60) {
        this.reset();
      }
    }
    draw() {
      const img = this.type === 'rose' ? redRoseImg : redGerberaImg;
      if (!img) return;

      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.rotate(this.rotation);
      ctx.globalAlpha = this.alpha;
      ctx.shadowBlur = 8;
      ctx.shadowColor = 'rgba(216, 27, 96, 0.4)';

      ctx.drawImage(img, -this.size / 2, -this.size / 2, this.size, this.size);

      ctx.restore();
    }
  }

  class ClickBurst {
    constructor(x, y) {
      this.x = x;
      this.y = y;
      this.size = Math.random() * 16 + 28;
      this.vx = (Math.random() - 0.5) * 6;
      this.vy = (Math.random() - 0.5) * 6 - 2;
      this.rotation = Math.random() * Math.PI * 2;
      this.rotSpeed = (Math.random() - 0.5) * 0.1;
      this.alpha = 1;
      this.decay = Math.random() * 0.02 + 0.015;
      this.type = Math.random() > 0.5 ? 'rose' : 'gerbera';
    }
    update() {
      this.x += this.vx;
      this.y += this.vy;
      this.vy += 0.05;
      this.rotation += this.rotSpeed;
      this.alpha -= this.decay;
    }
    draw() {
      if (this.alpha <= 0) return;
      const img = this.type === 'rose' ? redRoseImg : redGerberaImg;
      if (!img) return;

      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.rotate(this.rotation);
      ctx.globalAlpha = this.alpha;
      ctx.drawImage(img, -this.size / 2, -this.size / 2, this.size, this.size);
      ctx.restore();
    }
  }

  for (let i = 0; i < 70; i++) particles.push(new Particle());
  for (let i = 0; i < 30; i++) fallingFlowers.push(new FallingFlower());

  function animate() {
    ctx.clearRect(0, 0, width, height);

    particles.forEach(p => {
      p.update();
      p.draw();
    });

    fallingFlowers.forEach(f => {
      f.update();
      f.draw();
    });

    for (let i = clickBursts.length - 1; i >= 0; i--) {
      clickBursts[i].update();
      clickBursts[i].draw();
      if (clickBursts[i].alpha <= 0) {
        clickBursts.splice(i, 1);
      }
    }

    requestAnimationFrame(animate);
  }
  animate();

  window.addEventListener('click', (e) => {
    if (e.target.closest('.top-nav') || e.target.closest('.modal-card')) return;
    for (let i = 0; i < 12; i++) {
      clickBursts.push(new ClickBurst(e.clientX, e.clientY));
    }
  });


  // ==========================================
  // 2. SPOTIFY TRACK AUDIO PLAYER: SEASONS - PIANO VERSION (WAVE TO EARTH)
  // ==========================================
  let audioCtx = null;
  let isPlayingMusic = false;
  let musicTimer = null;

  const audioFile = new Audio('data:audio/mp3;base64,');
  audioFile.loop = true;

  const seasonsChords = [
    { bass: 98.00, notes: [196.00, 246.94, 293.66, 369.99], arpeggio: [392.00, 493.88, 587.33] },
    { bass: 92.50, notes: [185.00, 220.00, 277.18, 329.63], arpeggio: [369.99, 440.00, 554.37] },
    { bass: 82.41, notes: [164.81, 196.00, 246.94, 293.66], arpeggio: [329.63, 392.00, 493.88] },
    { bass: 110.00, notes: [220.00, 277.18, 329.63, 392.00], arpeggio: [440.00, 554.37, 659.25] },
    { bass: 73.42, notes: [146.83, 220.00, 277.18, 369.99], arpeggio: [440.00, 554.37, 739.99] },
    { bass: 123.47, notes: [246.94, 293.66, 369.99, 440.00], arpeggio: [493.88, 587.33, 739.99] }
  ];

  let currentStep = 0;

  function playWarmPianoNote(freq, time, duration, vol = 0.16) {
    if (!audioCtx) return;
    
    const osc1 = audioCtx.createOscillator();
    const gain1 = audioCtx.createGain();

    osc1.type = 'triangle';
    osc1.frequency.setValueAtTime(freq, time);

    gain1.gain.setValueAtTime(0.001, time);
    gain1.gain.exponentialRampToValueAtTime(vol, time + 0.03);
    gain1.gain.exponentialRampToValueAtTime(0.0001, time + duration);

    osc1.connect(gain1);
    gain1.connect(audioCtx.destination);

    osc1.start(time);
    osc1.stop(time + duration);
  }

  function playSeasonsBar() {
    if (!isPlayingMusic) return;
    if (!audioCtx) {
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    }
    if (audioCtx.state === 'suspended') {
      audioCtx.resume();
    }

    const now = audioCtx.currentTime;
    const chord = seasonsChords[currentStep % seasonsChords.length];

    playWarmPianoNote(chord.bass, now, 3.4, 0.24);

    chord.notes.forEach((freq, idx) => {
      playWarmPianoNote(freq, now + (idx * 0.06), 2.8, 0.12);
    });

    chord.arpeggio.forEach((freq, idx) => {
      playWarmPianoNote(freq, now + 0.5 + (idx * 0.35), 2.2, 0.10);
    });

    currentStep++;
  }

  const btnMusic = document.getElementById('btnMusic');
  btnMusic.addEventListener('click', () => {
    isPlayingMusic = !isPlayingMusic;

    if (isPlayingMusic) {
      btnMusic.classList.add('highlight');
      btnMusic.querySelector('.btn-text').innerText = 'Seasons On';

      audioFile.play().then(() => {
        // Playing
      }).catch(() => {
        playSeasonsBar();
        musicTimer = setInterval(playSeasonsBar, 2500);
      });

    } else {
      btnMusic.classList.remove('highlight');
      btnMusic.querySelector('.btn-text').innerText = 'Seasons Piano';
      
      if (audioFile) audioFile.pause();
      if (musicTimer) clearInterval(musicTimer);
    }
  });


  // ==========================================
  // 3. 3D TILT PARALLAX EFFECT
  // ==========================================
  const bouquetGraphic = document.getElementById('bouquetGraphic');

  document.addEventListener('mousemove', (e) => {
    const { clientX, clientY } = e;
    const { innerWidth, innerHeight } = window;
    
    const rotX = ((clientY / innerHeight) - 0.5) * -14;
    const rotY = ((clientX / innerWidth) - 0.5) * 14;

    bouquetGraphic.style.transform = `rotateX(${rotX}deg) rotateY(${rotY}deg)`;
  });


  // ==========================================
  // 4. LETTER MODAL CONTROLS
  // ==========================================
  const letterModal = document.getElementById('letterModal');
  const btnLetter = document.getElementById('btnLetter');
  const closeLetterModal = document.getElementById('closeLetterModal');
  const greetingCard = document.getElementById('greetingCard');

  function openLetter() {
    letterModal.classList.add('active');
    for (let i = 0; i < 20; i++) fallingFlowers.push(new FallingFlower());
  }

  btnLetter.addEventListener('click', openLetter);
  greetingCard.addEventListener('click', openLetter);

  closeLetterModal.addEventListener('click', () => {
    letterModal.classList.remove('active');
  });

  window.addEventListener('click', (e) => {
    if (e.target === letterModal) letterModal.classList.remove('active');
  });

  const btnRain = document.getElementById('btnRain');
  btnRain.addEventListener('click', () => {
    for (let i = 0; i < 30; i++) {
      fallingFlowers.push(new FallingFlower());
    }
  });

});
